(() => {
'use strict';
const $=s=>document.querySelector(s),form=$('#ed-form'),preview=$('#ed-preview'),overlay=$('#ed-overlay'),status=$('#ed-status'),tracks=window.SANTA_MUSIC;
let input=null,inputName='',inputURL='',musicFile=null,musicURL='',result=null,resultURL='',resultName='',job=0,worker=null,busy=false,loadJob=0;
for(const track of tracks)$('#ed-music').append(new Option(track.title,track.id));
const seconds=n=>`${Math.floor(n/60).toString().padStart(2,'0')}:${Math.floor(n%60).toString().padStart(2,'0')}`;
const range=()=>({start:Number($('#ed-start').value),end:Number($('#ed-end').value)});
function size(){const type=$('#ed-format').value;if(type==='vertical')return [720,1280];if(type==='square')return [720,720];if(type==='horizontal')return [1280,720];const scale=Math.min(1,1280/Math.max(preview.videoWidth||720,preview.videoHeight||1280));return [Math.max(2,Math.floor((preview.videoWidth||720)*scale/2)*2),Math.max(2,Math.floor((preview.videoHeight||1280)*scale/2)*2)];}
function caption(){const [w,h]=size();overlay.width=w;overlay.height=h;$('#ed-frame').style.aspectRatio=w+'/'+h;const c=overlay.getContext('2d');c.clearRect(0,0,w,h);const value=$('#ed-text').value.trim();if(!value)return;let font=Math.round(w*.07);c.font=`bold ${font}px Georgia,serif`;const words=value.split(/\s+/),lines=[];let line='';for(const word of words){const test=line?line+' '+word:word;if(c.measureText(test).width>w*.84&&line){lines.push(line);line=word;}else line=test;}if(line)lines.push(line);while(lines.some(l=>c.measureText(l).width>w*.86)&&font>12)c.font=`bold ${--font}px Georgia,serif`;const lh=font*1.23,padding=font*.5,boxH=lines.length*lh+padding*2,pos=$('#ed-position').value,y=pos==='top'?h*.08:pos==='center'?(h-boxH)/2:h-boxH-h*.1;c.fillStyle='#211522b8';c.fillRect(w*.045,y,w*.91,boxH);c.textAlign='center';c.textBaseline='top';c.fillStyle=$('#ed-color').value;c.shadowColor='#130a15';c.shadowBlur=5;lines.forEach((l,i)=>c.fillText(l,w/2,y+padding+i*lh));}
function clearResult(){if(resultURL)URL.revokeObjectURL(resultURL);resultURL='';result=null;$('#ed-result').pause();$('#ed-result').removeAttribute('src');$('#ed-result').hidden=true;$('#ed-download').disabled=true;window.SANTA_VIDEO_SHARE.update('ed',null,'');}
function change(){if(busy)return;clearResult();caption();const r=range();$('#ed-duration').textContent=Number.isFinite(r.end-r.start)&&r.end>r.start?`El archivo editado durará ${(r.end-r.start).toLocaleString('es-PE',{maximumFractionDigits:1})} segundos.`:'El final debe ser posterior al inicio.';$('#ed-volume-label').textContent=$('#ed-volume').value+' %';$('#ed-music-volume-label').textContent=$('#ed-music-volume').value+' %';status.textContent='Cambios preparados. Crea un nuevo MP4 para descargarlos o compartirlos.';preview.volume=Number($('#ed-volume').value)/100;$('#ed-audio-preview').volume=Number($('#ed-music-volume').value)/100;}
function valid(){const {start,end}=range();if(!input||!Number.isFinite(preview.duration)||!preview.videoWidth){status.textContent='Espera a que cargue el video.';return false;}if(!Number.isFinite(start)||!Number.isFinite(end)||start<0||end<=start||end>preview.duration+.05){status.textContent='Usa un inicio y un final válidos dentro de la duración del video.';return false;}if(end-start>600){status.textContent='Elige un fragmento de hasta 10 minutos para editar en el navegador.';return false;}return true;}
async function load(blob,name){if(busy){status.textContent='Cancela o termina la exportación antes de cambiar de video.';return;}if(!blob||!blob.size)return;if(blob.size>300*1024*1024){status.textContent='Elige un video de hasta 300 MB para este editor.';return;}clearResult();const id=++loadJob;input=null;$('#ed-settings').disabled=true;$('#ed-seek').disabled=true;preview.pause();if(inputURL)URL.revokeObjectURL(inputURL);inputURL=URL.createObjectURL(blob);inputName=name||'video-santa.mp4';preview.src=inputURL;
preview.onloadedmetadata=()=>{if(id!==loadJob)return;if(!Number.isFinite(preview.duration)||!preview.videoWidth){status.textContent='No se pudo leer la duración de este archivo. Elige otro video.';return;}input=blob;$('#ed-settings').disabled=false;$('#ed-seek').disabled=false;$('#ed-empty').hidden=true;$('#ed-start').value='0';$('#ed-end').value=String(Math.floor(preview.duration*10)/10);$('#ed-start').max=String(preview.duration);$('#ed-end').max=String(preview.duration);$('#ed-seek').max=String(preview.duration);$('#ed-input-status').textContent=`${inputName} · ${seconds(preview.duration)} · ${(blob.size/1048576).toFixed(1)} MB`;change();status.textContent='Video cargado. Ajusta tu copia y crea el MP4.';};preview.onerror=()=>{if(id===loadJob)status.textContent='Este navegador no puede abrir el video. Prueba con un MP4 H.264.';};}
window.SANTA_EDITOR={load};$('#ed-file').addEventListener('change',()=>{const file=$('#ed-file').files[0];if(file)load(file,file.name);});for(const el of form.querySelectorAll('input:not([type=file]),select,textarea'))el.addEventListener('input',change);
$('#ed-music').addEventListener('change',()=>{musicFile=null;$('#ed-audio').value='';if(musicURL)URL.revokeObjectURL(musicURL);musicURL='';const track=tracks.find(t=>t.id===$('#ed-music').value);$('#ed-audio-preview').pause();$('#ed-audio-preview').hidden=!track;if(track)$('#ed-audio-preview').src=track.src;else $('#ed-audio-preview').removeAttribute('src');change();});
$('#ed-audio').addEventListener('change',()=>{const file=$('#ed-audio').files[0];if(!file)return;if(file.size>40*1024*1024){status.textContent='Elige una pista de audio de hasta 40 MB.';return;}musicFile=file;$('#ed-music').value='none';if(musicURL)URL.revokeObjectURL(musicURL);musicURL=URL.createObjectURL(file);$('#ed-audio-preview').src=musicURL;$('#ed-audio-preview').hidden=false;change();});
$('#ed-seek').addEventListener('input',()=>{if(input)preview.currentTime=Number($('#ed-seek').value);});preview.addEventListener('timeupdate',()=>{$('#ed-seek').value=String(preview.currentTime);$('#ed-time').textContent=seconds(preview.currentTime)+' / '+seconds(preview.duration||0);if(!preview.paused&&preview.currentTime>=range().end)preview.pause();});preview.addEventListener('play',()=>{const r=range();if(preview.currentTime<r.start||preview.currentTime>=r.end)preview.currentTime=r.start;});window.addEventListener('aldea:navigate',()=>{preview.pause();$('#ed-audio-preview').pause();});
$('#ed-copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#ed-post').value);status.textContent='Descripción copiada. Pégala al publicar tu video.';}catch{$('#ed-post').focus();$('#ed-post').select();status.textContent='Texto seleccionado: cópialo para tu publicación.';}});
function lock(value){busy=value;$('#ed-settings').disabled=value||!input;$('#ed-file').disabled=value;$('#ed-seek').disabled=value||!input;$('#ed-cancel').hidden=!value;$('#ed-progress').hidden=!value;}
const png=()=>new Promise((resolve,reject)=>overlay.toBlob(b=>b?resolve(b):reject(new Error('No se pudo crear el mensaje.')),'image/png'));
async function bytes(path){const response=await fetch(path);if(!response.ok)throw new Error('No se pudo cargar un recurso del editor.');return new Uint8Array(await response.arrayBuffer());}
$('#ed-download').addEventListener('click',()=>{if(!result)return;const u=URL.createObjectURL(result),a=document.createElement('a');a.href=u;a.download=resultName;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000);});
form.addEventListener('submit',async e=>{e.preventDefault();if(busy||!form.reportValidity()||!valid())return;preview.pause();$('#ed-audio-preview').pause();clearResult();caption();const id=++job;lock(true);$('#ed-progress').value=0;status.textContent='Preparando tu editor…';try{
const {FFmpeg}=await import('./vendor/ffmpeg/index.js');if(id!==job)return;const ff=worker=new FFmpeg();const parts=await Promise.all([1,2].map(n=>bytes(`vendor/ffmpeg/core-${n}.bin`)));if(id!==job)return;const wasm=URL.createObjectURL(new Blob(parts,{type:'application/wasm'}));try{await ff.load({coreURL:new URL('vendor/ffmpeg/ffmpeg-core.js',document.baseURI).href,wasmURL:wasm});}finally{URL.revokeObjectURL(wasm);}if(id!==job)return;
await ff.writeFile('input-video',new Uint8Array(await input.arrayBuffer()));await ff.ffprobe(['-v','error','-show_entries','stream=codec_type','-of','json','input-video','-o','probe.json']);const probe=JSON.parse(new TextDecoder().decode(await ff.readFile('probe.json'))),hasAudio=probe.streams?.some(s=>s.codec_type==='audio');
const {start,end}=range(),duration=end-start,[w,h]=size(),withText=!!$('#ed-text').value.trim(),track=tracks.find(t=>t.id===$('#ed-music').value),withMusic=!!(musicFile||track),originalVolume=Number($('#ed-volume').value)/100,musicVolume=Number($('#ed-music-volume').value)/100;
const args=['-ss',String(start),'-t',String(duration),'-i','input-video'];let musicIndex=1;if(withText){await ff.writeFile('caption.png',new Uint8Array(await (await png()).arrayBuffer()));args.push('-loop','1','-i','caption.png');musicIndex++;}if(withMusic){await ff.writeFile('music-audio',musicFile?new Uint8Array(await musicFile.arrayBuffer()):await bytes(track.src));args.push('-stream_loop','-1','-i','music-audio');}
let filters=`[0:v]scale=${w}:${h}:force_original_aspect_ratio=decrease,pad=${w}:${h}:(ow-iw)/2:(oh-ih)/2:color=0x281b31,setsar=1[base]`;filters+=withText?';[base][1:v]overlay=0:0:shortest=1:format=auto,format=yuv420p[v]':';[base]format=yuv420p[v]';const audio=[];if(hasAudio&&originalVolume>0){filters+=`;[0:a]volume=${originalVolume},aresample=44100,apad,atrim=duration=${duration}[original]`;audio.push('[original]');}if(withMusic&&musicVolume>0){filters+=`;[${musicIndex}:a]volume=${musicVolume},aresample=44100,atrim=duration=${duration},afade=t=out:st=${Math.max(0,duration-1)}:d=1[music]`;audio.push('[music]');}if(audio.length===2)filters+=';[original][music]amix=inputs=2:duration=longest:normalize=0[a]';else if(audio.length===1)filters+=`;${audio[0]}anull[a]`;
args.push('-filter_complex',filters,'-map','[v]');if(audio.length)args.push('-map','[a]','-c:a','aac','-b:a','160k');else args.push('-an');args.push('-t',String(duration),'-r','24','-c:v','libx264','-preset','ultrafast','-crf','22','-pix_fmt','yuv420p','-movflags','+faststart','edited.mp4');ff.on('progress',p=>{if(id!==job)return;$('#ed-progress').value=Math.min(99,p.time/(duration*1000000)*100);status.textContent=`Creando el MP4 editado… ${Math.floor($('#ed-progress').value)} %`;});const code=await ff.exec(args,900000);if(id!==job)return;if(code!==0)throw new Error('No se pudo exportar. Prueba con un fragmento más corto o con otro archivo.');result=new Blob([await ff.readFile('edited.mp4')],{type:'video/mp4'});resultName='Editado-'+inputName.replace(/\.[^.]+$/,'').replace(/[^\p{L}\p{N}-]/gu,'-')+'.mp4';resultURL=URL.createObjectURL(result);$('#ed-result').src=resultURL;$('#ed-result').hidden=false;$('#ed-download').disabled=false;window.SANTA_VIDEO_SHARE.update('ed',result,resultName,$('#ed-post').value);$('#ed-progress').value=100;status.textContent='¡MP4 listo! Puedes reproducirlo, descargarlo o enviarlo al menú para compartir.';
}catch(error){if(id===job)status.textContent=error.message||'No se pudo crear el video. Inténtalo de nuevo.';}finally{if(id===job){worker?.terminate();worker=null;lock(false);}}});
$('#ed-cancel').addEventListener('click',()=>{++job;worker?.terminate();worker=null;lock(false);status.textContent='Exportación cancelada. Tus ajustes y el video original siguen disponibles.';});
})();
